use std::fs
use std::process

fn fail() {
    println("error")
    process::exit(1)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
        return
    }
    let head: Vec<string> = lines[0].split_whitespace().map(|x| x.to_string()).collect()
    if head.len() != 2 {
        fail()
        return
    }
    let r = head[0].parse::<int>().unwrap_or(0)
    let c = head[1].parse::<int>().unwrap_or(0)
    if r < 1 || c < 1 {
        fail()
        return
    }
    if (lines.len() as int) < r + 1 {
        fail()
        return
    }
    let mut grid: Vec<Vec<int>> = []
    let mut i = 0
    while i < r {
        let parts: Vec<string> = lines[(i + 1) as usize].split_whitespace().map(|x| x.to_string()).collect()
        if (parts.len() as int) != c {
            fail()
            return
        }
        let mut row: Vec<int> = []
        for p in parts {
            match p.parse::<int>() {
                Ok(v) => row.push(v),
                Err(_) => {
                    fail()
                    return
                }
            }
        }
        grid.push(row)
        i += 1
    }
    let mut out: Vec<string> = []
    let mut top = 0
    let mut bot = r - 1
    let mut left = 0
    let mut right = c - 1
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            out.push(grid[top as usize][j as usize].to_string())
            j += 1
        }
        top += 1
        j = top
        while j <= bot {
            out.push(grid[j as usize][right as usize].to_string())
            j += 1
        }
        right -= 1
        if top <= bot {
            j = right
            while j >= left {
                out.push(grid[bot as usize][j as usize].to_string())
                j -= 1
            }
            bot -= 1
        }
        if left <= right {
            j = bot
            while j >= top {
                out.push(grid[j as usize][left as usize].to_string())
                j -= 1
            }
            left += 1
        }
    }
    println(out.join(" "))
}

